import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final int MAX_N = 50;
    static final BigInteger LIMIT = BigInteger.valueOf(10).pow(18).add(BigInteger.ONE);

    static BigInteger[] dp = new BigInteger[MAX_N + 1];

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        BigInteger k = sc.nextBigInteger();
        sc.close();

        dp[0] = BigInteger.ONE;
        for (int i = 1; i <= n; i++) {
            dp[i] = BigInteger.ZERO;
            for (int j = 1; j <= i; j++) {
                BigInteger ways = dp[i - j].multiply(factorial(j - 1));
                dp[i] = dp[i].add(ways);
                if (dp[i].compareTo(LIMIT) > 0) dp[i] = LIMIT;
            }
        }

        boolean[] used = new boolean[n + 1];
        List<Integer> result = new ArrayList<>();
        solve(n, k, used, result);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < result.size(); i++) {
            if (i > 0) sb.append(' ');
            sb.append(result.get(i));
        }
        System.out.println(sb.toString());
    }

    static void solve(int n, BigInteger k, boolean[] used, List<Integer> result) {
        if (n == 0) return;

        int smallestAvailable = 1;
        while (smallestAvailable <= used.length - 1 && used[smallestAvailable]) {
            smallestAvailable++;
        }

        for (int len = 1; len <= n; len++) {
            BigInteger cnt = dp[n - len].multiply(factorial(len - 1));
            if (k.compareTo(cnt) > 0) {
                k = k.subtract(cnt);
                continue;
            }

            if (len == 1) {
                result.add(smallestAvailable);
                used[smallestAvailable] = true;
                solve(n - 1, k, used, result);
                return;
            }

            List<Integer> available = new ArrayList<>();
            for (int i = 1; i < used.length; i++) {
                if (!used[i]) available.add(i);
            }

            used[smallestAvailable] = true;
            List<Integer> others = new ArrayList<>();
            for (int x : available) {
                if (x != smallestAvailable) others.add(x);
            }

            BigInteger block = factorial(len - 1);
            BigInteger q = (k.subtract(BigInteger.ONE)).divide(block);
            BigInteger r = (k.subtract(BigInteger.ONE)).mod(block).add(BigInteger.ONE);

            int m = len - 1;
            int idx = q.intValue();

            List<Integer> subset = kthSubset(others, m, idx);
            List<Integer> subsetSorted = new ArrayList<>(subset);
            subsetSorted.sort(null);

            List<Integer> perm = kthPermutation(subsetSorted, r);

            result.add(smallestAvailable);
            for (int x : perm) {
                result.add(x);
                used[x] = true;
            }

            solve(n - len, r, used, result);
            return;
        }
    }

    static BigInteger factorial(int x) {
        BigInteger res = BigInteger.ONE;
        for (int i = 2; i <= x; i++) {
            res = res.multiply(BigInteger.valueOf(i));
            if (res.compareTo(LIMIT) > 0) return LIMIT;
        }
        return res;
    }

    static List<Integer> kthSubset(List<Integer> arr, int m, int k) {
        List<Integer> res = new ArrayList<>();
        int n = arr.size();
        for (int i = 0; i < n; i++) {
            if (m == 0) break;
            int rem = n - i - 1;
            if (rem < m - 1) {
                res.add(arr.get(i));
                m--;
            } else {
                BigInteger cnt = binomial(rem, m - 1);
                if (k < cnt.intValue()) {
                    res.add(arr.get(i));
                    m--;
                } else {
                    k -= cnt.intValue();
                }
            }
        }
        return res;
    }

    static BigInteger binomial(int n, int k) {
        if (k < 0 || k > n) return BigInteger.ZERO;
        if (k > n - k) k = n - k;
        BigInteger res = BigInteger.ONE;
        for (int i = 1; i <= k; i++) {
            res = res.multiply(BigInteger.valueOf(n - k + i)).divide(BigInteger.valueOf(i));
            if (res.compareTo(LIMIT) > 0) return LIMIT;
        }
        return res;
    }

    static List<Integer> kthPermutation(List<Integer> arr, BigInteger k) {
        List<Integer> available = new ArrayList<>(arr);
        List<Integer> res = new ArrayList<>();
        int m = available.size();
        for (int i = m; i >= 1; i--) {
            BigInteger fact = factorial(i - 1);
            BigInteger q = (k.subtract(BigInteger.ONE)).divide(fact);
            int idx = q.intValue();
            res.add(available.remove(idx));
            k = (k.subtract(BigInteger.ONE)).mod(fact).add(BigInteger.ONE);
        }
        return res;
    }
}
